insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'phonological-awareness'), 'overall', 0, 30, 'Developing', 'Sound-manipulation skills are still forming — breaking words into their component sounds and recombining them takes deliberate effort.', ARRAY['Practice saying words slowly, sound by sound, before trying to remove or blend a sound', 'Start with elision on simple one-syllable words before moving to blends and clusters', 'Read aloud regularly — hearing your own pronunciation reinforces the sound-to-letter mapping']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'phonological-awareness'), 'overall', 31, 50, 'Average', 'Comfortable with simple sound manipulation, but multi-sound blends and less common sound-matching pairs slow you down.', ARRAY['Practice blending 3-4 separate sounds into words without seeing them written first', 'Work on sound matching across less obvious pairs (matching endings, not just starts)']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'phonological-awareness'), 'overall', 51, 70, 'Strong', 'Reliable phonemic manipulation across elision, blending, and matching, with occasional slips on trickier consonant clusters.', ARRAY['Challenge yourself with elision on words with consonant blends (e.g. removing one sound from a three-consonant cluster)', 'Practice with multisyllabic words rather than just single syllables']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'phonological-awareness'), 'overall', 71, 85, 'Very Strong', 'Fast, accurate sound manipulation across all three skills — this level of phonological awareness underlies strong reading and spelling ability.', ARRAY['This skill transfers directly to learning new languages and to spelling irregular words', 'Try phonological awareness with unfamiliar or invented words to test the skill in isolation from memorized vocabulary']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'phonological-awareness'), 'overall', 86, 100, 'Exceptional', 'Expert-level phonological processing — sounds are manipulated automatically and accurately across every task type.', ARRAY['Consider how this strength could support tutoring, speech-language work, or language learning', 'This is a strong predictor of ease learning additional languages — a good time to try one']::text[], NULL, 5);
